import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';

const canvas=document.querySelector('#scene');
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false,powerPreference:'high-performance'});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.15;
const scene=new THREE.Scene();scene.background=new THREE.Color('#09171b');scene.fog=new THREE.FogExp2('#09171b',.021);
const camera=new THREE.PerspectiveCamera(54,innerWidth/innerHeight,.1,180);
scene.add(new THREE.HemisphereLight('#a9dcd2','#101820',1.45));
const key=new THREE.DirectionalLight('#c3fff1',2.2);key.position.set(-7,15,8);key.castShadow=true;key.shadow.mapSize.set(1024,1024);key.shadow.camera.left=-24;key.shadow.camera.right=24;key.shadow.camera.top=24;key.shadow.camera.bottom=-24;scene.add(key);
const cyan=new THREE.PointLight('#4de5d1',28,22);cyan.position.set(0,5,-4);scene.add(cyan);
const amber=new THREE.PointLight('#d99a58',18,17);amber.position.set(-9,3,1);scene.add(amber);
const blue=new THREE.PointLight('#4b9fe6',23,20);blue.position.set(9,4,0);scene.add(blue);
const mats={floor:new THREE.MeshStandardMaterial({color:'#16272b',roughness:.34,metalness:.45}),wall:new THREE.MeshStandardMaterial({color:'#142226',roughness:.56,metalness:.48}),dark:new THREE.MeshStandardMaterial({color:'#0b1417',roughness:.35,metalness:.7}),trim:new THREE.MeshStandardMaterial({color:'#42615e',metalness:.8,roughness:.23}),glow:new THREE.MeshStandardMaterial({color:'#65e3ce',emissive:'#26bfa9',emissiveIntensity:2.2,roughness:.25}),gold:new THREE.MeshStandardMaterial({color:'#c89259',emissive:'#7a4321',emissiveIntensity:.7,metalness:.7,roughness:.25}),glass:new THREE.MeshPhysicalMaterial({color:'#78bcb7',metalness:.12,roughness:.08,transparent:true,opacity:.32,transmission:.35}),stone:new THREE.MeshStandardMaterial({color:'#53605c',roughness:.8}),white:new THREE.MeshStandardMaterial({color:'#b8c5bd',roughness:.42,metalness:.35})};
function box(parent,x,y,z,sx,sy,sz,mat,opts={}){const m=new THREE.Mesh(new THREE.BoxGeometry(sx,sy,sz),mat);m.position.set(x,y,z);m.castShadow=opts.cast!==false;m.receiveShadow=true;parent.add(m);return m}
function cyl(parent,x,y,z,r1,r2,h,mat,seg=24){const m=new THREE.Mesh(new THREE.CylinderGeometry(r1,r2,h,seg),mat);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
function torus(parent,x,y,z,r,t,mat,rx=0){const m=new THREE.Mesh(new THREE.TorusGeometry(r,t,8,64),mat);m.position.set(x,y,z);m.rotation.x=rx;parent.add(m);return m}
// The Entrance: a quiet, impossible archive built from dark mineral and light.
const floor=box(scene,0,-.28,0,46,.5,46,mats.floor);floor.receiveShadow=true;
const grid=new THREE.GridHelper(44,44,'#35615e','#1b3537');grid.position.y=-.018;grid.material.transparent=true;grid.material.opacity=.21;scene.add(grid);
for(let i=-20;i<=20;i+=5){box(scene,i,0,-21,.08,10,.18,mats.trim,{cast:false});box(scene,i,0,21,.08,10,.18,mats.trim,{cast:false});box(scene,-21,0,i,.18,10,.08,mats.trim,{cast:false});box(scene,21,0,i,.18,10,.08,mats.trim,{cast:false});}
box(scene,0,5,-21,42,10,.5,mats.wall);box(scene,0,5,21,42,10,.5,mats.wall);box(scene,-21,5,0,.5,10,42,mats.wall);box(scene,21,5,0,.5,10,42,mats.wall);
for(let z=-16;z<=16;z+=8){for(const x of [-16,16]){cyl(scene,x,4,z,.55,.72,8,mats.dark,8);cyl(scene,x,4,z,.58,.58,.1,mats.glow,8);}}
// Architectural luminous rings, suspended sculptures and volumetric dust motes.
for(let i=0;i<4;i++){const ring=torus(scene,0,7+i*1.25,-3,8-i*.8,.045,i%2?mats.trim:mats.glow,Math.PI/2);ring.rotation.z=i*.22;}
for(let i=0;i<7;i++){const shard=new THREE.Mesh(new THREE.OctahedronGeometry(.55+Math.random()*.6,0),i%2?mats.glass:mats.trim);shard.position.set(-7+i*2.2,3.8+Math.sin(i*3)*1.25,-3-Math.cos(i)*2);shard.rotation.set(i,.3*i,.2*i);scene.add(shard);}
// Central missing-exhibit plinth and its hovering empty halo.
cyl(scene,0,.16,-2,2.05,2.4,.32,mats.dark,48);cyl(scene,0,.36,-2,1.55,1.75,.12,mats.trim,48);torus(scene,0,1.8,-2,1.22,.025,mats.glow);
const absence=new THREE.Group();absence.position.set(0,2.45,-2);scene.add(absence);const halo=torus(absence,0,0,0,.8,.025,mats.glow);halo.rotation.x=Math.PI/2;const core=new THREE.Mesh(new THREE.IcosahedronGeometry(.48,1),new THREE.MeshBasicMaterial({color:'#64e5d1',wireframe:true,transparent:true,opacity:.38}));absence.add(core);
// Exhibit-specific scenery / three interacting temporal anchors.
function pedestal(x,z,colorMat=mats.trim){cyl(scene,x,.28,z,.85,1,.48,mats.dark);cyl(scene,x,.55,z,.72,.72,.08,colorMat);}
pedestal(0,-8);cyl(scene,0,1.3,-8,.42,.55,1.45,mats.dark);const consoleRing=torus(scene,0,2.1,-8,.48,.035,mats.glow);consoleRing.rotation.x=Math.PI/2;box(scene,0,.98,-8,.62,.08,.62,mats.glow);
pedestal(8,1,mats.gold);const bridgeAnchor=new THREE.Group();bridgeAnchor.position.set(8,.7,1);scene.add(bridgeAnchor);cyl(bridgeAnchor,0,.4,0,.38,.48,.9,mats.dark);const bridgeOrb=new THREE.Mesh(new THREE.IcosahedronGeometry(.35,1),mats.gold);bridgeOrb.position.y=1.1;bridgeAnchor.add(bridgeOrb);torus(bridgeAnchor,0,1.1,0,.57,.035,mats.gold);
pedestal(-8,1);const statue=new THREE.Group();statue.position.set(-8,.62,1);scene.add(statue);cyl(statue,0,.72,0,.2,.3,1.35,mats.stone);const head=new THREE.Mesh(new THREE.IcosahedronGeometry(.42,1),mats.stone);head.position.y=1.7;statue.add(head);const glyph=new THREE.Group();glyph.position.set(0,1.85,.45);statue.add(glyph);const glyphRing=torus(glyph,0,0,0,.35,.035,mats.gold);glyphRing.rotation.y=Math.PI/2;for(let i=0;i<3;i++){const s=box(glyph,(i-1)*.16,0,0,.055,.33,.06,mats.gold);s.rotation.z=(i-1)*.25;}
// A bridge spans the exhibit's sunken channel when viewed in its future state.
box(scene,8,-.52,8,4,.28,16,mats.dark);for(let z=3;z<12;z+=2)box(scene,8,-.1,z,3.8,.1,.05,mats.trim,{cast:false});
const bridge=new THREE.Group();scene.add(bridge);bridge.visible=false;for(let i=0;i<5;i++){const plank=box(bridge,8,.12,3+i*1.65,3,.18,1.55,mats.glow);plank.material= i%2?mats.trim:mats.glow;}for(const x of [6.45,9.55]){const rail=box(bridge,x,.72,6.3,.12,.08,9,mats.glow);rail.rotation.x=.02;}
// The console is connected to its relay by a strip of luminous inlaid floor.
for(let z=-7;z<1;z+=1)box(scene,0,-.005,z,.035,.015,.48,mats.glow,{cast:false});
// Decorative branching portals hint at the other archived worlds.
const portalColors=['#60daca','#dfad70','#6da6e7','#d37bb8','#95db8c'];
for(let i=0;i<5;i++){const x=-14+i*7.1;const arch=torus(scene,x,3.15,-19.5,2.1,.12,new THREE.MeshStandardMaterial({color:portalColors[i],emissive:portalColors[i],emissiveIntensity:.75,metalness:.45,roughness:.25}));arch.scale.y=1.46;box(scene,x,1.3,-19.5,3.15,2.6,.15,mats.dark);const veil=new THREE.Mesh(new THREE.PlaneGeometry(3,4.7),new THREE.MeshBasicMaterial({color:portalColors[i],transparent:true,opacity:.09,side:THREE.DoubleSide}));veil.position.set(x,2.7,-19.35);scene.add(veil);}
// Dust motes.
const dustGeo=new THREE.BufferGeometry(),dustN=460,dustPos=new Float32Array(dustN*3);for(let i=0;i<dustN;i++){dustPos[i*3]=(Math.random()-.5)*40;dustPos[i*3+1]=Math.random()*9;dustPos[i*3+2]=(Math.random()-.5)*40;}dustGeo.setAttribute('position',new THREE.BufferAttribute(dustPos,3));const dust=new THREE.Points(dustGeo,new THREE.PointsMaterial({color:'#a9e3d8',size:.035,transparent:true,opacity:.52}));scene.add(dust);
// Arka, built from simple sculptural forms; responsive shadows and movement.
const player=new THREE.Group();scene.add(player);player.position.set(0,0,10);
const suit=new THREE.MeshStandardMaterial({color:'#24383a',metalness:.55,roughness:.32}),coat=new THREE.MeshStandardMaterial({color:'#d2ded7',metalness:.18,roughness:.55}),skin=new THREE.MeshStandardMaterial({color:'#b77e61',roughness:.65});
const body=box(player,0,1.22,0,.57,.78,.34,suit);const chest=box(player,0,1.36,-.19,.47,.47,.1,coat);const headMesh=new THREE.Mesh(new THREE.SphereGeometry(.22,16,12),skin);headMesh.position.set(0,1.88,-.02);player.add(headMesh);const visor=box(player,0,1.89,-.207,.31,.095,.025,mats.glow,{cast:false});
const legs=[];for(const x of [-.17,.17]){const leg=box(player,x,.52,0,.19,.63,.24,suit);legs.push(leg);box(player,x,.16,-.055,.23,.17,.37,mats.dark);}
const arms=[];for(const x of [-.39,.39])arms.push(box(player,x,1.25,0,.16,.62,.19,suit));
// Collectible memory fragment, visible after all three temporal anchors align.
const relic=new THREE.Group();relic.position.set(0,1.35,-2);scene.add(relic);const relicMesh=new THREE.Mesh(new THREE.TetrahedronGeometry(.62,1),new THREE.MeshPhysicalMaterial({color:'#ffd99b',emissive:'#c87c35',emissiveIntensity:1.6,metalness:.6,roughness:.12,transmission:.2}));relic.add(relicMesh);for(let i=0;i<3;i++){const r=torus(relic,0,0,0,.95+i*.25,.022,mats.gold);r.rotation.set(i*.65,i*.8,0);}relic.visible=false;

