relic.visible=false;

const $=s=>document.querySelector(s),hud=$('#hud'),title=$('#title-screen'),journal=$('#journal'),settings=$('#settings'),ending=$('#ending');
const saveKey='museum-tomorrow-save-v1';let saved=null;try{saved=JSON.parse(localStorage.getItem(saveKey)||'null')}catch{}
let playing=false,yaw=0,pitch=.12,moveX=0,moveZ=0,run=false,jump=0,jumpVel=0,temporal='present',target=null,echoMode=0,artifact=0,restored={console:false,bridge:false,statue:false},toastTimer=0,elapsed=0,lastSave=0;
if(saved){restored={...restored,...saved.restored};artifact=saved.artifact||0;}
const targetDefs=[{id:'console',name:'RESONANCE CONSOLE',obj:new THREE.Vector3(0,0,-8),required:'future',hint:'RESTORE POWER'},{id:'bridge',name:'FUTURE BRIDGE',obj:new THREE.Vector3(8,0,1),required:'future',hint:'SHIFT POSSIBILITY'},{id:'statue',name:'MEMORY STATUE',obj:new THREE.Vector3(-8,0,1),required:'past',hint:'REVEAL MEMORY'},{id:'relic',name:'THE MISSING EXHIBIT',obj:new THREE.Vector3(0,1.3,-2),required:'present',hint:'RECOVER ARTIFACT'}];
function save(){try{localStorage.setItem(saveKey,JSON.stringify({restored,artifact,player:[player.position.x,player.position.z],at:Date.now()}));const s=$('#save-indicator');s.classList.add('show');setTimeout(()=>s.classList.remove('show'),900);}catch{}}
function progress(){const n=Object.values(restored).filter(Boolean).length;$('#progress-fill').style.width=`${Math.max(12,n/3*100)}%`;$('#artifact-count').textContent=String(artifact).padStart(2,'0');$('#objective-text').textContent=n<3?'Restore the exhibit power':artifact?'The exhibit is restored':'Recover the missing artifact';if(n===3&&!relic.visible){relic.visible=true;absence.visible=false;showToast('THE EXHIBIT IS BACK. SOMETHING REMEMBERS YOU.');save();}}
function showToast(t){const el=$('#toast');el.textContent=t;el.classList.remove('hidden');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.add('hidden'),2500)}
function dialogue(text){$('#echo-text').textContent=text;$('#echo-card').classList.remove('hidden');}
function closeDialogue(){ $('#echo-card').classList.add('hidden'); }
function start(){playing=true;title.classList.add('leaving');hud.classList.remove('hidden');if(saved?.player){player.position.x=saved.player[0]||0;player.position.z=saved.player[1]||10;}progress();if(!saved)dialogue('Welcome, Keeper Arka. The central exhibit has been erased from the record. I can still hear its resonance in three anchors. Find them—and please, do not trust every future you see.');}
$('#start-btn').addEventListener('click',start);
$('#journal-btn').addEventListener('click',()=>journal.classList.remove('hidden'));
$('#settings-btn').addEventListener('click',()=>settings.classList.remove('hidden'));
document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>b.closest('.modal').classList.add('hidden')));
$('#echo-continue').addEventListener('click',closeDialogue);
$('#replay-btn').addEventListener('click',()=>{ending.classList.add('hidden');restored={console:false,bridge:false,statue:false};artifact=0;relic.visible=false;absence.visible=true;player.position.set(0,0,10);echoMode=0;progress();save();});
document.querySelectorAll('.time-rail button').forEach(b=>b.addEventListener('click',()=>{temporal=b.dataset.state;document.querySelectorAll('.time-rail button').forEach(q=>q.classList.toggle('active',q===b));if(target){$('#temporal-name').textContent=target.name;}else $('#temporal-name').textContent='NO SIGNAL';}));
$('#collection-tab').addEventListener('click',()=>{const c=$('#journal-content');document.querySelectorAll('.journal-tabs button').forEach(b=>b.classList.remove('selected'));$('#collection-tab').classList.add('selected');c.innerHTML=`<h3>RECOVERED MEMORIES</h3><p>${artifact?'The Mnemonic Seed — a future made real by being remembered.':'No artifacts recovered yet. The empty plinth is waiting.'}</p><div class="note-row"><span>◇</span><p>Mnemonic Seed / central exhibit</p><b>${artifact?'RECOVERED':'UNKNOWN'}</b></div><div class="note-row"><span>⌁</span><p>Temporal anchors aligned</p><b>${Object.values(restored).filter(Boolean).length} / 3</b></div>`;});
document.querySelector('.journal-tabs button').addEventListener('click',()=>{document.querySelectorAll('.journal-tabs button').forEach(b=>b.classList.remove('selected'));document.querySelector('.journal-tabs button').classList.add('selected');$('#journal-content').innerHTML='<h3>THE VANISHING EXHIBIT</h3><p>On my first night as Keeper, the central exhibit was gone. Its absence is spreading—whole futures are being erased from the archive.</p><div class="note-row"><span>01</span><p>Meet ECHO at the Resonance Console.</p><b>IN PROGRESS</b></div><div class="note-row"><span>02</span><p>Restore the three temporal anchors.</p><b>LOCKED</b></div><div class="note-row"><span>03</span><p>Recover the missing artifact.</p><b>LOCKED</b></div>';});
$('#language').addEventListener('change',e=>showToast(e.target.value==='Bahasa Indonesia'?'Bahasa akan diterapkan pada dialog berikutnya.':'Language set to English'));
$('#graphics').addEventListener('change',e=>{const scale=e.target.value==='Low'?1:e.target.value==='Medium'?1.25:e.target.value==='Ultra'?2:1.6;renderer.setPixelRatio(Math.min(devicePixelRatio,scale));showToast(`GRAPHICS · ${e.target.value.toUpperCase()}`)});
$('#sensitivity').addEventListener('input',e=>sensitivity=Number(e.target.value)/5);
let sensitivity=1;
function act(){if(!playing)return;if(!target){showToast('NO TEMPORAL OBJECT IN RANGE');return;}if(target.id==='console'&&echoMode===0&&!restored.console){echoMode=1;dialogue('The console is listening. In its future state, it can still draw power from the exhibit that should exist. Set its timeline to FUTURE, then use it.');return;}if(target.id==='relic'){if(!relic.visible)return;artifact=1;relic.visible=false;progress();save();showToast('ARTIFACT RECOVERED · MNEMONIC SEED');ending.classList.remove('hidden');return;}
 if(restored[target.id]){showToast(`${target.name} · ANCHOR ALREADY ALIGNED`);return;}
 if(temporal!==target.required){const hint=target.id==='statue'?'The inscription is older than the stone. Try PAST.':'A future signal is still present. Try FUTURE.';showToast(hint);return;}
 restored[target.id]=true;
 if(target.id==='console'){box(scene,0,1.18,-8,.42,.55,.42,mats.glow);consoleRing.material=mats.glow;echoMode=2;dialogue('Signal restored. One memory returned: the museum was built by a civilization that had not been born yet. The statue and the bridge share its signature.');}
 if(target.id==='bridge'){bridge.visible=true;bridgeOrb.material=mats.glow;bridgeAnchor.children[0].material=mats.glow;showToast('FUTURE BRIDGE MANIFESTED · MEMORY ANCHOR 02');}
 if(target.id==='statue'){glyph.visible=true;statue.children[0].material=mats.gold;showToast('A HIDDEN MEMORY UNFOLDS · MEMORY ANCHOR 03');}
 progress();save();}
$('#use-btn').addEventListener('click',act);window.addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.code==='KeyW'||e.code==='ArrowUp')moveZ=1;if(e.code==='KeyS'||e.code==='ArrowDown')moveZ=-1;if(e.code==='KeyA'||e.code==='ArrowLeft')moveX=-1;if(e.code==='KeyD'||e.code==='ArrowRight')moveX=1;if(e.code==='ShiftLeft'||e.code==='ShiftRight')run=true;if(e.code==='Space'){jumpVel=5.5;}if(e.code==='KeyE'||e.code==='Enter')act();if(e.code==='KeyJ')journal.classList.toggle('hidden');if(e.code==='Escape'){journal.classList.add('hidden');settings.classList.add('hidden');closeDialogue();}});window.addEventListener('keyup',e=>{if(['KeyW','ArrowUp','KeyS','ArrowDown'].includes(e.code))moveZ=0;if(['KeyA','ArrowLeft','KeyD','ArrowRight'].includes(e.code))moveX=0;if(e.code==='ShiftLeft'||e.code==='ShiftRight')run=false;});
$('#jump-btn').addEventListener('pointerdown',()=>jumpVel=5.5);$('#run-btn').addEventListener('pointerdown',()=>run=true);['pointerup','pointercancel','pointerleave'].forEach(ev=>$('#run-btn').addEventListener(ev,()=>run=false));

