function updateTarget(){let best=null,dist=4.2;for(const t of targetDefs){if(t.id==='relic'&&!relic.visible)continue;if(t.id!=='relic'&&restored[t.id])continue;const d=Math.hypot(player.position.x-t.obj.x,player.position.z-t.obj.z);if(d<dist){dist=d;best=t;}}target=best;const prompt=$('#interact-prompt');if(best){prompt.classList.remove('hidden');$('#prompt-text').textContent=best.hint;$('#temporal-name').textContent=best.name;}else{prompt.classList.add('hidden');$('#temporal-name').textContent='NO SIGNAL';}}
function updateWorld(dt){elapsed+=dt;const speed=(run?6.4:3.6),f=moveZ,r=moveX,mag=Math.hypot(f,r);if(mag>.04){const fx=-Math.sin(yaw),fz=-Math.cos(yaw),rx=Math.cos(yaw),rz=-Math.sin(yaw);player.position.x+=(fx*f+rx*r)/Math.max(1,mag)*speed*dt;player.position.z+=(fz*f+rz*r)/Math.max(1,mag)*speed*dt;player.rotation.y=Math.atan2(-(fx*f+rx*r),-(fz*f+rz*r));}
 player.position.x=THREE.MathUtils.clamp(player.position.x,-19.2,19.2);player.position.z=THREE.MathUtils.clamp(player.position.z,-19.1,19.1);if(jumpVel||jump>0){jump+=jumpVel*dt;jumpVel-=14*dt;if(jump<0){jump=0;jumpVel=0;}}player.position.y=jump;const walking=mag>.08,phase=elapsed*(run?12:8);legs[0].rotation.x=walking?Math.sin(phase)*.6:0;legs[1].rotation.x=walking?-Math.sin(phase)*.6:0;arms[0].rotation.x=walking?-Math.sin(phase)*.36:0;arms[1].rotation.x=walking?Math.sin(phase)*.36:0;body.position.y=1.22+(walking?Math.abs(Math.sin(phase*2))*.035:0);
 const px=player.position.x+Math.sin(yaw)*7.1,py=3.35+pitch*3.4,pz=player.position.z+Math.cos(yaw)*7.1;camera.position.lerp(new THREE.Vector3(px,py,pz),1-Math.exp(-5*dt));camera.lookAt(player.position.x,1.35+pitch*2,player.position.z-1.6);
 updateTarget();bridge.visible=restored.bridge||(target?.id==='bridge'&&temporal==='future');bridge.traverse(o=>{if(o.isMesh){o.material=o.material===mats.glow?mats.glow:mats.trim;o.material.transparent=!restored.bridge;o.material.opacity=restored.bridge?1:.33;}});glyph.visible=restored.statue||(target?.id==='statue'&&temporal==='past');if(target?.id==='statue'&&temporal==='past')glyph.children.forEach(o=>{if(o.material)o.material=mats.glow;});else if(!restored.statue)glyph.children.forEach(o=>{if(o.material)o.material=mats.gold;});
 absence.rotation.y=elapsed*.18;core.rotation.y=-elapsed*.24;relic.rotation.y=elapsed*.35;relic.position.y=1.35+Math.sin(elapsed*1.5)*.12;for(let i=0;i<dustN;i++)dustPos[i*3+1]+=(Math.sin(elapsed*.3+i)*.0004);dustGeo.attributes.position.needsUpdate=true;}
function frame(now){requestAnimationFrame(frame);const dt=Math.min(.04,(now-(frame.last||now))/1000);frame.last=now;if(playing)updateWorld(dt);else{elapsed+=dt;camera.position.lerp(new THREE.Vector3(10,7,15),1-Math.exp(-dt*.28));camera.lookAt(0,2,-3);absence.rotation.y=elapsed*.14;for(const s of scene.children){if(s.geometry?.type==='TorusGeometry'&&s.position.y>5)s.rotation.z+=dt*.04;}}renderer.render(scene,camera);if(playing&&now-lastSave>30000){save();lastSave=now;}}
requestAnimationFrame(frame);
window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));});
